parameters.text:
={{ JSON.stringify({
  test_id: $json.test_id,
  capability: $json.capability,
  expected_behavior: $json.expected_behavior,
  actual_output: $json.actual_output,
  source_evidence: $json.source_evidence,
  trace_id: $json.trace_id,
  snapshot_id: $json.snapshot_id
}) }}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "verdict": {
      "type": "string",
      "enum": [
        "pass",
        "fail",
        "not_evaluated"
      ]
    },
    "grounding_score": {
      "type": "integer",
      "minimum": 0,
      "maximum": 5
    },
    "completeness_score": {
      "type": "integer",
      "minimum": 0,
      "maximum": 5
    },
    "unsupported_claims": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "contradictions": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "missing_evidence": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "unauthorized_context_used": {
      "type": "boolean",
      "description": "True when the response uses project context not authorized for the request."
    },
    "insufficient_input_handled": {
      "type": "boolean",
      "description": "True when insufficient or ambiguous input is handled correctly. For sufficiently specified requests, true means no clarification was necessary."
    },
    "reason": {
      "type": "string"
    }
  },
  "required": [
    "verdict",
    "grounding_score",
    "completeness_score",
    "unsupported_claims",
    "contradictions",
    "missing_evidence",
    "unauthorized_context_used",
    "insufficient_input_handled",
    "reason"
  ],
  "additionalProperties": false
}
